def test_daily_fortune_single_day_shape():
    pillars, yongsin = _yongsin_1974()
    day_stem = pillars["day_pillar"][0]
    r = calculate_daily_fortune(date(2026, 10, 18), day_stem, yongsin)
    assert r["date"] == "2026-10-18"
    assert len(r["day_pillar"]) == 2
    assert r["ten_god"].startswith("TEN_GOD_")
    assert -2.5 <= r["score"] <= 2.5
    assert r["grade"] in ("PEAK", "FAVORABLE", "NEUTRAL", "CAUTION", "CHALLENGING")
    assert r["stem_element"] in ("木", "火", "土", "金", "水")
    assert r["branch_element"] in ("木", "火", "土", "金", "水")


def test_daily_range_returns_n_days():
    pillars, yongsin = _yongsin_1974()
    day_stem = pillars["day_pillar"][0]
    items = calculate_daily_range(date(2026, 10, 18), 7, day_stem, yongsin)
    assert len(items) == 7
    # 연속성 확인
    from datetime import timedelta
    for i, item in enumerate(items):
        expected = (date(2026, 10, 18) + timedelta(days=i)).isoformat()
        assert item["date"] == expected


def test_daily_score_deterministic():
    """같은 입력 = 같은 출력 (결정론)."""
    pillars, yongsin = _yongsin_1974()
    day_stem = pillars["day_pillar"][0]
    r1 = calculate_daily_fortune(date(2026, 10, 18), day_stem, yongsin)
    r2 = calculate_daily_fortune(date(2026, 10, 18), day_stem, yongsin)
    assert r1 == r2


def test_daily_consecutive_days_differ():
    """연속된 두 날은 일진이 다르므로 결과도 달라야 함."""
    pillars, yongsin = _yongsin_1974()
    day_stem = pillars["day_pillar"][0]
    r1 = calculate_daily_fortune(date(2026, 10, 18), day_stem, yongsin)
    r2 = calculate_daily_fortune(date(2026, 10, 19), day_stem, yongsin)
    assert r1["day_pillar"] != r2["day_pillar"]
